      if(ui.attemptsMin&&r.attempts<Number(ui.attemptsMin))return false; if(ui.lastContact&&r.lastContact!==ui.lastContact)return false; if(ui.source&&(l.origem||"Base")!==ui.source)return false; if(ui.loss&&r.negotiation.lossReason!==ui.loss)return false; return true;
