    var periods=[["today","Hoje"],["week","Esta semana"],["month","Este mês"],["30","Últimos 30 dias"],["year","Este ano"],["all","Todo o período"],["custom","Personalizado"]],rows=sortedSegmentRows(),selected=ui.reportSegmentId==="all"?metricsForLeadSet(leads,reportRange()):(rows.find(function(row){return row.id===ui.reportSegmentId;})||metricsForLeadSet([],reportRange())),selectedName=ui.reportSegmentId==="all"?"Todos os segmentos":segmentName(ui.reportSegmentId);
    var actions='<button class="btn" data-view="dashboard">'+icon("chart")+'Ver dashboard</button>',h=topHead("Relatórios por Segmento","Compare resultados reais e descubra os nichos com melhor conversão",actions);
    h+='<section class="report-toolbar"><div class="field"><label>Período</label><select class="control" data-report-filter="reportPeriod">'+periods.map(function(item){return '<option value="'+item[0]+'" '+(ui.reportPeriod===item[0]?'selected':'')+'>'+item[1]+'</option>';}).join("")+'</select></div>'+(ui.reportPeriod==="custom"?'<div class="field"><label>Data inicial</label><input class="control" type="date" value="'+attr(ui.reportStart)+'" data-report-filter="reportStart"></div><div class="field"><label>Data final</label><input class="control" type="date" value="'+attr(ui.reportEnd)+'" data-report-filter="reportEnd"></div>':'')+'<div class="field report-segment-field"><label>Detalhar segmento</label><select class="control" data-report-filter="reportSegmentId"><option value="all">Todos os segmentos</option>'+state.segments.map(function(segment){return '<option value="'+attr(segment.id)+'" '+(ui.reportSegmentId===segment.id?'selected':'')+'>'+esc(segment.name)+'</option>';}).join("")+'</select></div></section>';
