  function renderSegmentFunnel(metrics){var steps=[{label:"Leads",value:metrics.leads},{label:"Contatos",value:metrics.contacts},{label:"Reuniões",value:metrics.meetings},{label:"Propostas",value:metrics.proposals},{label:"Vendas",value:metrics.sales}],max=Math.max(1,metrics.leads);return '<div class="segment-funnel">'+steps.map(function(step,index){var previous=index?steps[index-1].value:0;return '<div class="segment-funnel-step" style="--funnel-width:'+Math.max(12,step.value/max*100)+'%"><span>'+step.label+'</span><strong>'+step.value+'</strong>'+(index?'<em>'+percent(rate(step.value,previous))+' da etapa anterior</em>':'<em>Base do período</em>')+'</div>';}).join("")+'</div>';}
