  function saveProposalDraft(){var draft=ProposalModule.normalizeProposal(ui.proposalDraft),existing=state.proposals.list.find(function(item){return item.id===draft.id;}),previousLeadId=existing&&existing.leadId,numberTaken=state.proposals.list.some(function(item){return item.id!==draft.id&&normalize(item.number)===normalize(draft.number);});if(!draft.number||numberTaken){toast(numberTaken?"Já existe uma proposta com esse número.":"Informe o número da proposta.",true);return false;}if(!draft.client.name&&!draft.client.company){toast("Informe o cliente ou a empresa.",true);return false;}if(!draft.items.length){toast("Adicione pelo menos um serviço ou produto.",true);return false;}draft.updatedAt=nowISO();if(existing)Object.assign(existing,draft);else{draft.id=ProposalModule.uid("proposal");draft.createdAt=draft.createdAt||nowISO();state.proposals.list.push(draft);state.proposals.nextNumber++;}if(previousLeadId&&previousLeadId!==draft.leadId)syncLeadProposalValue(previousLeadId);syncLeadProposalValue(draft.leadId);state.proposals.company=ProposalModule.clone(ui.proposalCompanyDraft);save(true);ui.proposalDraft=null;ui.proposalCompanyDraft=null;ui.proposalMode="list";render();toast(existing?"Proposta atualizada.":"Proposta criada.");return true;}
