    var totals={};items.forEach(function(item){var key=item.type+"|"+item.category;totals[key]=(totals[key]||0)+item.amount;});var rows=Object.keys(totals).map(function(key){var p=key.split("|");return {type:p[0],name:p.slice(1).join("|"),amount:totals[key]};}).sort(function(a,b){return b.amount-a.amount;}).slice(0,8);
    return '<div class="finance-category-list">'+rows.map(function(row){return '<div><span><i class="'+row.type+'"></i>'+esc(row.name)+'</span><b>'+financeMoney(row.amount)+'</b></div>';}).join("")+'</div>';
