  function applyProposalInput(el){if(!ui.proposalDraft)return false;if(el.dataset.proposalField){var numeric=["discount","surcharge","payment.downPayment","payment.installments","payment.installmentValue"].includes(el.dataset.proposalField);setObjectPath(ui.proposalDraft,el.dataset.proposalField,numeric?Number(el.value)||0:el.value);updateProposalLive();return true;}if(el.dataset.companyField){setObjectPath(ui.proposalCompanyDraft,el.dataset.companyField,el.value);updateProposalLive();return true;}if(el.dataset.proposalItem!==undefined){var item=ui.proposalDraft.items[Number(el.dataset.proposalItem)];if(item){item[el.dataset.itemField]=["quantity","unitPrice"].includes(el.dataset.itemField)?Number(el.value)||0:el.value;updateProposalLive();}return true;}return false;}
  function handleChange(e){var el=e.target,id=ui.drawerId;if(el.closest("#contact-export-form")){updateContactExportModal();return;}if(el.dataset.proposalLead!==undefined){var lead=getLead(el.value);ui.proposalDraft.leadId=lead?lead.id:"";if(lead)ui.proposalDraft.client={name:lead.contato||"",company:lead.nome||"",document:"",phone:lead.telefone||"",whatsapp:lead.whatsapp||"",email:lead.email||"",address:lead.endereco||""};render();return;}if(applyProposalInput(el))return;if(el.dataset.catalogFilter){ui[el.dataset.catalogFilter]=el.value;render();return;}if(el.dataset.reportFilter){ui[el.dataset.reportFilter]=el.value;render();return;}if(el.dataset.financialFilter){ui[el.dataset.financialFilter]=el.value;if(el.dataset.financialFilter==="financialType")ui.financialCategory="all";refreshFinancial();return;}if(el.dataset.financeType!==undefined){var financeForm=el.closest("form"),categorySelect=financeForm.querySelector("[data-finance-category]");categorySelect.innerHTML=financialCategoryOptions(el.value,"",true);var categoryField=financeForm.querySelector("[data-new-finance-category]");if(categoryField)categoryField.hidden=true;return;}if(el.dataset.financeCategory!==undefined){var customField=el.closest("form").querySelector("[data-new-finance-category]");customField.hidden=el.value!=="__new__";customField.querySelector("input").required=el.value==="__new__";return;}if(el.id==="business-segment-filter"){ui.segmentId=segmentExists(el.value)?el.value:"all";state.lastSegmentId=ui.segmentId;save(true);render();return;}if(el.dataset.importPolicy!==undefined){updateImportConfirm();return;}if(el.dataset.segmentSelect!==undefined){var form=el.closest("form"),newField=form&&form.querySelector("[data-new-segment-field]");if(newField){newField.hidden=el.value!=="__new__";var input=newField.querySelector("input");if(input)input.required=el.value==="__new__";}else if(el.value==="__new__"&&id){el.value=segmentIdFor(getLead(id));openCreateSegmentModal({leadId:id});return;}}if(el.dataset.stageId){requestStage(el.dataset.stageId,el.value);return;}if(el.dataset.filterField!==undefined){ui[el.dataset.filterField]=el.value;render();return;}if(!id)return;var r=rec(id);if(el.dataset.profile){r.profile[el.dataset.profile]=el.value;rebuildLeads();save();render();renderDrawer();}else if(el.dataset.contact){r.contact[el.dataset.contact]=el.value;save();}else if(el.dataset.record){r[el.dataset.record]=el.dataset.record==="attempts"?Number(el.value)||0:el.value;save();render();}else if(el.dataset.next){var controls=document.querySelectorAll("[data-next]"),a={};controls.forEach(function(x){a[x.dataset.next]=x.value;});setNextAction(id,a);render();renderDrawer();}else if(el.dataset.neg){r.negotiation[el.dataset.neg]=el.dataset.neg==="demoReady"?el.value==="true":el.value;save();render();renderDrawer();}}
  function handleClick(e){
    var b=e.target.closest("button,a,[data-open-lead]"),action=b&&b.dataset.action;
    if(!e.target.closest(".global-search-wrap"))closeSearchSuggestions();
    if(e.target.closest(".stage-select"))return;
    if(b&&b.dataset.modalClose!==undefined){e.preventDefault();closeModal();return;}
    if(action){e.preventDefault();var id=b.dataset.id;
      if(action==="clear-search"){var globalSearch=document.getElementById("global-search");globalSearch.value="";updateSearchControls();closeSearchSuggestions();render();globalSearch.focus();}else if(action==="open-search-result"){closeSearchSuggestions();openDrawer(id,"resumo");}else if(action==="view-search-results"){closeSearchSuggestions();ui.view="leads";render();document.getElementById("view-root").focus();}else if(action==="new-lead")openNewLead(); else if(action==="new-task")openTaskModal(); else if(action==="new-proposal")startProposal(); else if(action==="cancel-proposal"||action==="back-proposals"){ui.proposalMode="list";ui.proposalDraft=null;ui.proposalCompanyDraft=null;render();}else if(action==="edit-proposal")startProposal(id,false);else if(action==="duplicate-proposal")startProposal(id,true);else if(action==="preview-proposal"){ui.proposalPreviewId=id;ui.proposalMode="preview";render();}else if(action==="print-proposal"){ui.proposalPreviewId=id;ui.proposalMode="preview";render();setTimeout(function(){window.print();},40);}else if(action==="print-draft-proposal"){updateProposalLive();setTimeout(function(){window.print();},40);}else if(action==="delete-proposal")openProposalDelete(id);else if(action==="add-custom-proposal-item"){ui.proposalDraft.items.push(ProposalModule.normalizeLine({description:"Novo item",quantity:1,unitPrice:0,unit:"serviço",source:"custom"}));render();}else if(action==="add-catalog-proposal-item"){var catalogItem=state.proposals.catalog.find(function(item){return item.id===id;});if(catalogItem){ui.proposalDraft.items.push(ProposalModule.normalizeLine({catalogItemId:catalogItem.id,description:catalogItem.name+(catalogItem.description?" - "+catalogItem.description:""),quantity:1,unitPrice:catalogItem.defaultValue,unit:catalogItem.unit,source:"catalog"}));ui.proposalCatalogSearch="";render();}}else if(action==="remove-proposal-item"){ui.proposalDraft.items.splice(Number(b.dataset.index),1);render();}else if(action==="new-catalog-item")openCatalogModal();else if(action==="edit-catalog-item")openCatalogModal(id);else if(action==="delete-catalog-item")openCatalogDelete(id);else if(action==="toggle-catalog-item"){var toggleItem=state.proposals.catalog.find(function(item){return item.id===id;});if(toggleItem){toggleItem.active=!toggleItem.active;toggleItem.updatedAt=nowISO();save(true);render();}}else if(action==="new-financial")openFinancialModal(); else if(action==="edit-financial")openFinancialModal(id); else if(action==="delete-financial")openFinancialDelete(id); else if(action==="open-data")openDataModal(); else if(action==="close-drawer")closeDrawer(); else if(action==="start-prospect")startProspecting(); else if(action==="call"){var l=getLead(id);if(l){window.location.href="tel:"+l.telefone;}}
      else if(action==="whatsapp")openWhatsAppModal(id); else if(action==="copy-phone"){var ph=(getLead(id)||{}).telefone||"";if(navigator.clipboard)navigator.clipboard.writeText(ph);toast("Telefone copiado.");}
      else if(action==="quick-result")openResultModal(id); else if(action==="add-history"){closeModal();openHistoryNote(id||ui.drawerId);} else if(action==="complete-task")completeTask(b.dataset.key); else if(action==="reschedule")reschedule(b.dataset.key); else if(action==="agenda-item"){if(!b.dataset.openLead)reschedule(b.dataset.key);}
      else if(action==="toggle-advanced"){ui.advanced=!ui.advanced;render();}else if(action==="clear-filters"){["city","stage","scoreMin","reviewsMin","ratingMin","attemptsMin","lastContact","source","loss"].forEach(function(k){ui[k]="";});ui.quickFilter="todos";ui.scoreBand="all";render();}
      else if(action==="agenda-prev"){ui.agendaAnchor=addDays(ui.agendaAnchor,ui.agendaMode==="hoje"?-1:-7);render();}else if(action==="agenda-next"){ui.agendaAnchor=addDays(ui.agendaAnchor,ui.agendaMode==="hoje"?1:7);render();}else if(action==="agenda-today"){ui.agendaAnchor=todayKey();render();}
      else if(action==="backup-json")exportJSON();else if(action==="export-contacts")openContactExportModal();else if(action==="export-csv")exportCSV();else if(action==="import-leads")openImportSourceModal();else if(action==="import-paste")openPasteImport();else if(action==="import-sheet")document.getElementById("file-spreadsheet").click();else if(action==="restore-backup")document.getElementById("file-backup").click();
      else if(action==="create-segment")openCreateSegmentModal();else if(action==="rename-segment")openRenameSegmentModal(b.dataset.segmentId);else if(action==="delete-segment")openDeleteSegmentModal(b.dataset.segmentId);
      else if(action==="save-settings")saveSettings(); else if(action==="mark-proposal"){var rp=rec(id);rp.negotiation.proposalStatus="Enviada";changeStage(id,"proposta_enviada");logEvent(id,"proposal","Proposta enviada",money(potential(id)));save();render();renderDrawer();toast("Proposta registrada.");}
      else if(action==="end-prospect"){ui.prospect=null;closeModal();render();}else if(action==="prospect-next")advanceProspect(1);else if(action==="prospect-prev")advanceProspect(-1);return;
    }
    if(b&&b.dataset.view){ui.view=b.dataset.view;render();document.getElementById("view-root").focus();return;}
    if(b&&b.dataset.viewAgenda){ui.view="agenda";render();return;}
    if(b&&b.dataset.themeChoice){var selectedTheme=b.dataset.themeChoice,resolvedTheme=applyTheme(selectedTheme,true);render();toast(selectedTheme==="system"?"Tema sincronizado com o sistema.":resolvedTheme==="light"?"Tema claro ativado.":"Tema escuro ativado.");return;}
    if(b&&b.dataset.filter){ui.quickFilter=b.dataset.filter;render();return;}
    if(b&&b.dataset.sort){ui.sort={field:b.dataset.sort,asc:ui.sort.field===b.dataset.sort?!ui.sort.asc:true};render();return;}
    if(b&&b.dataset.reportSort){ui.reportSort={field:b.dataset.reportSort,asc:ui.reportSort.field===b.dataset.reportSort?!ui.reportSort.asc:false};render();return;}
    if(b&&b.dataset.reportSegment){ui.reportSegmentId=b.dataset.reportSegment;render();return;}
    if(b&&b.dataset.agendaMode){ui.agendaMode=b.dataset.agendaMode;ui.agendaAnchor=todayKey();render();return;}
    if(b&&b.dataset.period){ui.dashboardPeriod=b.dataset.period;render();return;}
    if(b&&b.dataset.drawerTab){ui.drawerTab=b.dataset.drawerTab;renderDrawer();return;}
    if(b&&b.dataset.result){recordResult(b.dataset.id,b.dataset.result,b.dataset.advance==="1");return;}
    if(b&&b.dataset.waTemplate){openWhatsApp(b.dataset.id,b.dataset.waTemplate);return;}
    if(b&&b.dataset.openLead){if(b.dataset.openLead)openDrawer(b.dataset.openLead,"resumo");else{ui.view="agenda";render();}return;}
  }
  function completeTask(key){if(key.indexOf("lead:")===0){var id=key.slice(5),a=rec(id).nextAction;if(a)logEvent(id,"followup",a.type+" concluído",a.note||"");rec(id).nextAction=null;}else{var t=state.tasks.find(function(x){return x.id===key.slice(5);});if(t)t.done=true;}save();render();toast("Tarefa concluída.");}
  function reschedule(key){var item=scheduleItems().find(function(x){return x.key===key;});if(item)openTaskModal(item);}
  function saveSettings(){state.settings.sellerName=document.getElementById("set-seller").value.trim()||"Vendedor";state.settings.defaultValue=Number(document.getElementById("set-value").value)||0;document.querySelectorAll("[data-template]").forEach(function(el){state.settings.templates[el.dataset.template]=el.value;});Object.keys(defaultGoals()).forEach(function(key){var target=document.getElementById("goal-"+key+"-target"),period=document.getElementById("goal-"+key+"-period");state.settings.goals[key]={target:Math.max(1,parseInt(target.value,10)||defaultGoals()[key].target),period:period.value==="month"?"month":"week"};});save(true);render();toast("Configurações salvas.");}
  function openWhatsApp(id,key){var l=getLead(id),r=rec(id),n=r.negotiation,phone=digits(r.contact.whatsapp||l.whatsapp||l.telefone);if(!phone){toast("Este lead não possui WhatsApp.",true);return;}var text=key==="blank"?"":state.settings.templates[key]||"",vars={empresa:l.nome||"",contato:r.contact.name||l.contato||"",meu_nome:state.settings.sellerName||"",demo:n.demoUrl||"",valor:money(potential(id))};Object.keys(vars).forEach(function(k){text=text.split("{"+k+"}").join(vars[k]);});logEvent(id,"whatsapp","WhatsApp aberto",TEMPLATE_NAMES[key]||"Sem template");save();closeModal();window.open("https://wa.me/"+phone+(text?"?text="+encodeURIComponent(text):""),"_blank","noopener");if(ui.drawerId===id)renderDrawer();}

  document.addEventListener("click",handleClick);
  document.addEventListener("submit",handleSubmit);
  window.addEventListener("mica-sync",function(event){setSaveState(event.detail.kind,event.detail.message);});
  document.addEventListener("change",handleChange);
  document.addEventListener("input",function(e){var el=e.target;if(el.dataset.contactExportInput!==undefined){updateContactExportModal(false);return;}if(applyProposalInput(el))return;if(el.dataset.proposalCatalogSearch!==undefined){ui.proposalCatalogSearch=el.value;var results=document.querySelector(".proposal-picker-results");if(results){results.innerHTML=renderProposalPickerResults();hydrateIcons(results);}return;}if(el.dataset.catalogSearch!==undefined){ui.catalogSearch=el.value;render();var search=document.querySelector("[data-catalog-search]");if(search){search.focus();search.setSelectionRange(search.value.length,search.value.length);}return;}if(el.dataset.financialSearch!==undefined){ui.financialSearch=el.value;refreshFinancial(true);}});
  document.getElementById("drawer-scrim").addEventListener("click",closeDrawer);
  function updateSearchControls(){var input=document.getElementById("global-search"),clear=document.querySelector(".search-clear");if(clear)clear.hidden=!input.value.trim();}
  var runLeadSearch=SearchModule.debounce(function(){renderSearchSuggestions();if(ui.view==="leads"||ui.view==="pipeline")render();},220);
  document.getElementById("global-search").addEventListener("input",function(){updateSearchControls();runLeadSearch();});
  document.getElementById("global-search").addEventListener("focus",function(){if(this.value.trim())renderSearchSuggestions();});
  document.getElementById("file-spreadsheet").addEventListener("change",function(){var f=this.files[0];this.value="";if(f)importSpreadsheet(f);});
  document.getElementById("file-backup").addEventListener("change",function(){var f=this.files[0];this.value="";if(f)restoreBackup(f);});
  document.addEventListener("keydown",function(e){var tag=(e.target.tagName||"").toLowerCase(),typing=["input","textarea","select"].includes(tag),suggestions=document.getElementById("search-suggestions");if(e.key==="Escape"){if(suggestions&&!suggestions.hidden){closeSearchSuggestions();document.getElementById("global-search").focus();}else if(document.getElementById("modal-layer").classList.contains("is-open")){ui.prospect=null;closeModal();}else if(ui.drawerId)closeDrawer();}else if(e.key==="/"&&!typing){e.preventDefault();document.getElementById("global-search").focus();}else if((e.key==="n"||e.key==="N")&&!typing)openNewLead();});
  document.addEventListener("dragstart",function(e){var card=e.target.closest("[data-drag-id]");if(!card)return;ui.dragId=card.dataset.dragId;card.classList.add("is-dragging");e.dataTransfer.effectAllowed="move";e.dataTransfer.setData("text/plain",ui.dragId);});
  document.addEventListener("dragend",function(e){var card=e.target.closest("[data-drag-id]");if(card)card.classList.remove("is-dragging");ui.dragId=null;document.querySelectorAll(".pipeline-column").forEach(function(x){x.classList.remove("is-over");});});
  document.addEventListener("dragover",function(e){var col=e.target.closest("[data-drop-stage]");if(!col||!ui.dragId)return;e.preventDefault();document.querySelectorAll(".pipeline-column").forEach(function(x){x.classList.toggle("is-over",x===col);});});
  document.addEventListener("drop",function(e){var col=e.target.closest("[data-drop-stage]");if(!col||!ui.dragId)return;e.preventDefault();var id=ui.dragId;ui.dragId=null;requestStage(id,col.dataset.dropStage);});

  function handleSystemThemeChange(){if(themePreference()==="system")applyTheme("system",false);}
  if(THEME_MEDIA.addEventListener)THEME_MEDIA.addEventListener("change",handleSystemThemeChange);else if(THEME_MEDIA.addListener)THEME_MEDIA.addListener(handleSystemThemeChange);
  applyTheme(themePreference(),false); if(window.createMicaSidebar)sidebar=window.createMicaSidebar(); hydrateIcons(document); setSaveState("saved","Salvo na nuvem"); render();
